pub unsafe extern "C" fn sv_validate_public_base_url_binding(
    args_ptr: *mut u8,
    args_len: usize,
) -> u64 {
    let args_json = read_string(args_ptr, args_len);
    pack(run_envelope_sync(|| {
        let args = args_map(&args_json)?;
        let public_base_url = require_string(&args, "publicBaseUrl")?;
        match validate_public_base_url(&public_base_url) {
            None => Ok(Value::Null),
            Some(message) => Ok(Value::String(message.to_owned())),
        }
    }))
}

/// Binding for `buildPayableToolResult` (allow-path unwrap of a branded response envelope).
///
/// # Safety
///
/// `args_ptr` / `args_len` must describe a valid guest allocation from `sv_alloc`.
#[no_mangle]
pub unsafe extern "C" fn sv_build_payable_tool_result_binding(
    args_ptr: *mut u8,
    args_len: usize,
) -> u64 {
    let args_json = read_string(args_ptr, args_len);
    pack(run_envelope_sync(|| {
        let args = args_map(&args_json)?;
        let envelope: ResponseEnvelope = require_typed(&args, "envelope")?;
        to_value(&build_payable_tool_result(&envelope))
    }))
}

/// Binding for `invokePayableNext`.
///
/// # Safety
///
/// `args_ptr` / `args_len` must describe a valid guest allocation from `sv_alloc`.
#[no_mangle]
pub unsafe extern "C" fn sv_invoke_payable_next_binding(args_ptr: *mut u8, args_len: usize) -> u64 {
    let args_json = read_string(args_ptr, args_len);
    pack(run_envelope_sync(|| {
        let args = args_map(&args_json)?;
        let state = optional_value(&args, "state");
        let event = optional_value(&args, "event");
        result_as_value(invoke_payable_next(state.as_ref(), event.as_ref()))
    }))
}

fn optional_views(args: &Map<String, Value>) -> Result<Option<Vec<String>>, SdkError> {
    match args.get("views") {
        None => Ok(None),
        Some(Value::Array(items)) => {
            let mut views = Vec::with_capacity(items.len());
            for item in items {
                match item.as_str() {
                    Some(s) => views.push(s.to_owned()),
                    None => {
                        return Err(SdkError::transport(
                            "args.views must be an array of strings".to_owned(),
                            false,
                        ));
                    }
                }
            }
            Ok(Some(views))
        }
        Some(_) => Err(SdkError::transport(
            "args.views must be an array when present".to_owned(),
            false,
        )),
    }
}

fn optional_branding(args: &Map<String, Value>) -> Result<Option<MerchantBranding>, SdkError> {
    match args.get("branding") {
        None | Some(Value::Null) => Ok(None),
        Some(Value::Object(map)) => Ok(Some(MerchantBranding {
            brand_name: optional_string_field(map, "brandName")?,
            icon_url: optional_string_field(map, "iconUrl")?,
            logo_url: optional_string_field(map, "logoUrl")?,
        })),
        Some(_) => Err(SdkError::transport(
            "args.branding must be an object when present".to_owned(),
            false,
        )),
    }
}

fn optional_string_field(map: &Map<String, Value>, key: &str) -> Result<Option<String>, SdkError> {
    match map.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(Value::String(s)) => Ok(Some(s.clone())),
        Some(_) => Err(SdkError::transport(
            format!("args.branding.{key} must be a string when present"),
            false,
        )),
    }
}
